import{_ as e,o,c as r,a2 as s}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"2019-02-11 :: Ceph Orchestration Meeting","description":"","frontmatter":{"title":"2019-02-11 :: Ceph Orchestration Meeting","date":"2019-02-11T00:00:00.000Z","updated":"2019-02-23T00:00:00.000Z","tags":["Ceph","分布式存储","自动化","云计算","系统管理"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-02-11_-_-_Ceph_Orchestration_Meeting.md","filePath":"posts/2019/2019-02-11_-_-_Ceph_Orchestration_Meeting.md","lastUpdated":1780460162000}'),n={name:"posts/2019/2019-02-11_-_-_Ceph_Orchestration_Meeting.md"};function p(a,t,_,i,c,h){return o(),r("div",null,[...t[0]||(t[0]=[s("<p>本次会议主要讨论了Ceph项目的多个重要议题，包括会议纪要损坏、设备清单刷新、Cats实现、库存过滤器标签、添加/删除主机、Rook问题和OpenShift安装器。</p><p><strong>会议纪要损坏问题</strong>： 上次会议的会议纪要由于多人同时编辑而损坏，现已恢复。</p><p><strong>设备清单刷新</strong>： 讨论了在Rook和DeepSea等 orchestrator 中触发设备清单刷新的问题，决定提供一个刷新标志，但不会在Rook或DeepSea中实现缓存。</p><p><strong>Cats实现</strong>： 讨论了为所有 orchestrator 实现Cats（缓存）的可行性，决定将Cats作为一个服务实现。</p><p><strong>库存过滤器标签</strong>： 讨论了是否应该在库存过滤器中使用标签，决定将标签保留在orchestrator中，但不会在通用接口中使用。</p><p><strong>添加/删除主机</strong>： 讨论了是否应该在orchestrator接口中保留添加/删除主机的功能，决定保留该功能。</p><p><strong>Rook问题</strong>： 讨论了Rook在创建OSD时出现的问题，Sebastian Han正在调查这个问题。</p><p><strong>OpenShift安装器</strong>： 讨论了使用OpenShift安装器部署Ceph的问题，决定调查使用Ansible Runner Service的Ansible实现。</p><p>会议还制定了相应的行动计划，包括调查Rook创建OSD时的问题、探索使用Ansible Runner Service的Ansible实现，以及确定下次面对面会议的时间和地点。</p>",9)])])}const l=e(n,[["render",p]]);export{d as __pageData,l as default};
